using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using System.Diagnostics;
namespace DanceStudio;

public enum PreviousOutputAction { Keep, Archive, Cancel }
public sealed record PreviousOutput(string Path,string ExportId,string ManifestHash,Dictionary<string,string> Files);
public sealed record ExportReview(string NewFolder,string PackageId,string ProjectId,string Kind,IReadOnlyList<PreviousOutput> Previous);
public sealed record ExportReceipt(string Folder,string? Backup,IReadOnlyList<string> Warnings);
public static class PackageUpdates {
 [ThreadStatic]static List<string>? scanWarnings;
 public static ExportReceipt? LastReceipt{get;internal set;}
 public static void RequireGameClosed(){if(Process.GetProcessesByName("SkyrimSE").Length>0)throw new IOException(UiText.T("releaseGameRunning"));}
 public static string Hash(string path){using var f=File.OpenRead(path);return Convert.ToHexStringLower(SHA256.HashData(f));}
 public static void SafeTree(string root,string parent){root=Path.GetFullPath(root);var boundary=Path.GetFullPath(parent).TrimEnd(Path.DirectorySeparatorChar);if(!root.StartsWith(boundary+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Output path escapes selected directory");for(var d=new DirectoryInfo(root);d!=null&&(d.FullName==boundary||d.FullName.StartsWith(boundary+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase));d=d.Parent)if(d.Exists&&(d.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Linked output directories cannot be modified");var stack=new Stack<(string path,int depth)>();if(Directory.Exists(root))stack.Push((root,0));int count=0;while(stack.TryPop(out var current)){foreach(string entry in Directory.EnumerateFileSystemEntries(current.path)){if(++count>512||current.depth>8)throw new IOException("Package tree budget");var attributes=File.GetAttributes(entry);if((attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Linked output resources cannot be modified");if((attributes&FileAttributes.Directory)!=0)stack.Push((entry,current.depth+1));}}}
 public static (HashSet<uint> Tokens,Dictionary<string,long> Times) Inventory(string parent){scanWarnings=[];var tokens=new HashSet<uint>();var times=new Dictionary<string,long>();int count=0;foreach(string folder in Directory.EnumerateDirectories(parent)){if(++count>8192)throw new IOException("Output directory scan limit reached");string file=Path.Combine(folder,"song.json");try{if(!File.Exists(file)||new FileInfo(file).Length>1024*1024)continue;using var d=JsonDocument.Parse(File.ReadAllText(file));var j=d.RootElement;if(j.TryGetProperty("token",out var token)&&token.ValueKind==JsonValueKind.Number&&token.TryGetUInt32(out uint value)&&value>0)tokens.Add(value);if(j.TryGetProperty("id",out var id)&&id.ValueKind==JsonValueKind.String&&j.TryGetProperty("exportedAt",out var time)&&time.ValueKind==JsonValueKind.Number&&time.TryGetInt64(out long stamp)&&stamp>=0&&stamp<=253402300799999L){string key=id.GetString()!;times[key]=Math.Max(times.GetValueOrDefault(key),stamp);}}catch(Exception e)when(e is IOException or JsonException or InvalidOperationException or UnauthorizedAccessException){}}return(tokens,times);}

 static Dictionary<string,string> Files(string folder){var files=Directory.EnumerateFiles(folder,"*",new EnumerationOptions{RecurseSubdirectories=true,AttributesToSkip=0,MaxRecursionDepth=8}).Take(65).ToArray();if(files.Length>64)throw new IOException("Package file count exceeds limit");return files.ToDictionary(f=>Path.GetRelativePath(folder,f).Replace('\\','/'),Hash,StringComparer.OrdinalIgnoreCase);}
 public static void Validate(string folder){
  using var d=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"song.json")));var j=d.RootElement;if(j.GetProperty("schemaVersion").GetInt32()!=4)throw new InvalidDataException("Expected game package schema 4");var hashes=j.GetProperty("hashes");double duration=j.GetProperty("duration").GetDouble();if(!double.IsFinite(duration)||duration<=0||duration>1800||!j.TryGetProperty("projectId",out _)||!Guid.TryParse(j.GetProperty("exportId").GetString(),out _))throw new InvalidDataException("Invalid package metadata");foreach(var key in new[]{"music","dance","danceFemale","danceMale","cameraSamples","facialTimeline"})if(j.TryGetProperty(key,out var track)){string name=track.GetString()!;if(key=="dance"&&name=="mt_idle.hkx")name=j.GetProperty("danceFemale").GetString()!;if(!hashes.TryGetProperty(name,out _))throw new InvalidDataException("Required track hash missing: "+key);}if(!j.TryGetProperty("music",out _)||!j.TryGetProperty("dance",out _)&&!j.TryGetProperty("cameraSamples",out _))throw new InvalidDataException("Package track missing");foreach(var pair in hashes.EnumerateObject()){string rel=pair.Name.Replace('\\','/');if(rel.Equals("mt_idle.hkx",StringComparison.OrdinalIgnoreCase))continue;if(Path.IsPathRooted(rel)||rel.Split('/').Any(x=>x is ".." or "."||x.Contains(':')))throw new InvalidDataException("Unsafe package hash path");string file=Path.Combine(folder,rel);if(Hash(file)!=pair.Value.GetString()?.ToLowerInvariant())throw new InvalidDataException("Package integrity failure: "+rel);}
  bool dance=j.TryGetProperty("dance",out _);uint token=j.GetProperty("token").GetUInt32();if(dance){if(token==0||token>16777215||j.GetProperty("oarSubmod").GetString()!="DS_"+token)throw new InvalidDataException("OAR token/submod mismatch");using var c=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"config.json")));var config=c.RootElement;if(config.GetProperty("name").GetString()!="DS_"+token||config.GetProperty("conditions")[1].GetProperty("Value B").GetProperty("value").GetUInt32()!=token)throw new InvalidDataException("OAR selector mismatch");foreach(string name in new[]{"male/mt_idle.hkx","female/mt_idle.hkx"})if(!hashes.TryGetProperty(name,out _))throw new InvalidDataException("Dance hash missing");}else if(token!=0||File.Exists(Path.Combine(folder,"config.json")))throw new InvalidDataException("Camera-only package contains dance selection");
 }
 public static List<PreviousOutput> Find(string parent,string id,string projectId,string kind){var result=new List<PreviousOutput>();scanWarnings=[];if(!Directory.Exists(parent))return result;foreach(string folder in Directory.EnumerateDirectories(parent).Take(8193)){if(result.Count>512)throw new IOException("Too many previous outputs");if(Path.GetFileName(folder).StartsWith('.'))continue;string manifest=Path.Combine(folder,"song.json");if(!File.Exists(manifest)||new FileInfo(manifest).Length>1024*1024)continue;bool matching=false;try{SafeTree(folder,parent);using var d=JsonDocument.Parse(File.ReadAllText(manifest));var j=d.RootElement;if(j.GetProperty("id").GetString()!=id||j.GetProperty("projectId").GetString()!=projectId||!Guid.TryParse(j.GetProperty("exportId").GetString(),out _))continue;string actual=SongProject.PackageKind(j.TryGetProperty("dance",out _),j.TryGetProperty("cameraSamples",out _));if(actual!=kind)continue;if(j.TryGetProperty("packageKind",out var declaredKind)&&declaredKind.GetString()!=actual)continue;matching=true;Validate(folder);var files=Files(folder);var expected=j.GetProperty("hashes").EnumerateObject().Select(p=>p.Name).Where(name=>!name.Equals("mt_idle.hkx",StringComparison.OrdinalIgnoreCase)||File.Exists(Path.Combine(folder,name))).Append("song.json").Concat(j.TryGetProperty("dance",out _)?new[]{"config.json"}:[]).ToHashSet(StringComparer.OrdinalIgnoreCase);if(!expected.SetEquals(files.Keys)){scanWarnings.Add(UiText.T("releaseKeptUser")+folder);continue;}result.Add(new(Path.GetFullPath(folder),j.GetProperty("exportId").GetString()!,Hash(manifest),files));}catch(Exception e)when(e is IOException or JsonException or InvalidOperationException or KeyNotFoundException or FormatException){if(matching)scanWarnings.Add(UiText.T("releaseKeptUnverified")+folder+": "+e.Message);}}
  return result;
 }
 static bool Unchanged(PreviousOutput old,string parent){SafeTree(old.Path,parent);var files=Files(old.Path);return files.Count==old.Files.Count&&files.All(p=>old.Files.TryGetValue(p.Key,out var h)&&h==p.Value);}
 public static ExportReceipt Commit(string parent,string staged,string destination,ExportReview review,PreviousOutputAction action){
  parent=Path.GetFullPath(parent);SafeTree(staged,parent);SafeTree(destination,parent);Validate(staged);RequireGameClosed();if(action==PreviousOutputAction.Cancel)throw new OperationCanceledException(UiText.T("releaseExportCancelled"));string? backup=null;var notes=new List<string>(scanWarnings??[]);
  if(action==PreviousOutputAction.Archive&&review.Previous.Count>0){foreach(var old in review.Previous)if(!Unchanged(old,parent))throw new IOException(UiText.T("releaseOutputChanged"));string backupRoot=Path.Combine(parent,".LDA-R-backups");Directory.CreateDirectory(backupRoot);SafeTree(Path.Combine(backupRoot,".path-check"),parent);string temp=Path.Combine(backupRoot,Guid.NewGuid().ToString("N")+".tmp");backup=Path.ChangeExtension(temp,".zip");try{using(var z=ZipFile.Open(temp,ZipArchiveMode.Create))foreach(var old in review.Previous)foreach(var file in old.Files)z.CreateEntryFromFile(Path.Combine(old.Path,file.Key),Path.GetFileName(old.Path)+"/"+file.Key,CompressionLevel.Fastest);using(var z=ZipFile.OpenRead(temp))foreach(var old in review.Previous)foreach(var file in old.Files){using var stream=z.GetEntry(Path.GetFileName(old.Path)+"/"+file.Key)!.Open();if(Convert.ToHexStringLower(SHA256.HashData(stream))!=file.Value)throw new IOException("Backup integrity failure");}File.Move(temp,backup);}finally{if(File.Exists(temp))File.Delete(temp);}}
  // The old packages have not been changed. Failed publication leaves all of them usable.
  RequireGameClosed();Directory.Move(staged,destination);
  if(backup!=null)foreach(var old in review.Previous){try{RequireGameClosed();if(!Unchanged(old,parent)){notes.Add(UiText.T("releaseOutputChanged")+" "+old.Path);continue;}string quarantine=Path.Combine(parent,".LDA-R-retired-"+Guid.NewGuid().ToString("N"));Directory.Move(old.Path,quarantine);try{SafeTree(quarantine,parent);Directory.Delete(quarantine,true);}catch(Exception e){notes.Add(UiText.T("releaseKeptArchive")+quarantine+": "+e.Message);}}catch(Exception e){notes.Add(UiText.T("releaseKeptPrevious")+old.Path+": "+e.Message);}}
  return LastReceipt=new(destination,backup,notes);
 }
}
